(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,2627,e=>{"use strict";var i=e.i(43476),l=e.i(11337);function n(e){let n={li:"li",p:"p",strong:"strong",ul:"ul",...(0,l.useMDXComponents)(),...e.components},{AnketaCollapse:r,AnketaGroup:c,AnketaList:d,AnketaPoint:h,AnketaProse:j,Whisper:x}=n;return r||s("AnketaCollapse",!0),c||s("AnketaGroup",!0),d||s("AnketaList",!0),h||s("AnketaPoint",!0),j||s("AnketaProse",!0),x||s("Whisper",!0),(0,i.jsxs)(c,{children:[(0,i.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,i.jsxs)(d,{children:[(0,i.jsxs)(h,{title:"Имя персонажа [русс|англ]",children:[(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"Джулия Контарини | Julia Contarini"})}),(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"«Жуля», «Джу», «Жулечка» — уменьшительно-ласкательные формы, которые можно считать смертным приговором, если вы не являетесь Давеном Бренденом;"}),"\n",(0,i.jsx)(n.li,{children:"«Госпожа Джулия» — наиболее идеальный вариант обращения, применимый преимущественно для слуг;"}),"\n",(0,i.jsx)(n.li,{children:"«Джулия» — простое обращение;"}),"\n",(0,i.jsx)(n.li,{children:"«Эмине» — новое имя после принятия ислама (принудительного). Скрывает, не желая пятнать свою жизнь в Энкраже;"}),"\n",(0,i.jsx)(n.li,{children:"«Жрица Солнца» — прозвище, возникшее благодаря характерной способности воссоздавать яркое сияние утренней и закатной зари. Императорский Змей нарёк её данным титулом исходя из того, что девушка всегда «следует за Солнцем», а значит, за новым правителем – и обязана быть на его стороне;"}),"\n",(0,i.jsx)(n.li,{children:"«Зимняя» Джулия — приставка, которую грешники порой любят добавлять к имени, говорящая о том, что девушка является выходцем из логова на северных землях."}),"\n"]})]}),(0,i.jsx)(h,{title:"Возраст",children:(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"прожитый на земле: 32 года."}),"\n",(0,i.jsx)(n.li,{children:"дата рождения — 03.05.1563г. | смерти — 28.12.1595г."}),"\n",(0,i.jsx)(n.li,{children:"прожитый в Загробном мире как грешная душа: 423 года"}),"\n"]})}),(0,i.jsx)(h,{title:"Пол",children:(0,i.jsx)(n.p,{children:"Женский"})}),(0,i.jsxs)(h,{title:"Раса",children:[(0,i.jsx)(n.p,{children:"Вуивр."}),(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Происхождение с одной из благороднейших семей на то время венецианских земель — рода Контарини — Джулия практически никогда не знала ни голода, ни холода. С самого детства окружающие богатства заставляли возрасти довольно горделивой и благородной девушке, знающей ценность своим богатствам и статусу, привыкшей к соответствующему обращению. Даже путь монастыря, кажется, эту черту не исправил, лишь притаил, но в гареме позволил ей всецело расцвести. Ситуация не меняется даже в переломный момент, связанный со становлением рабыней и необходимостью прислуживать госпоже: приобщаясь, Джулия поняла ценность своей жизни, придала значение могуществу и власти, умению подстраивать под себя ситуацию, позволяя алчности взять над собой верх и, по возможности, обогащаться за средства богатых господ для личных целей."}),"\n"]})]})]})}),(0,i.jsxs)(r,{title:"Психологический профиль",children:[(0,i.jsx)(r,{title:"Характер",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"«Величие кроется в истинно могущественных и благородных личностях, способных добровольной жертвой нести бремя ответственности за тех, кто принял свою сторону». Джулия Контарини — стремящийся к своему совершенствованию и позиционированию лидер, обладающий склонностью к проявлению властности и довольно сильной настойчивости. Она, не чувствуя себя скованной уже в привычном ей мире, позволила себе развить позицию решительного руководителя, готового к тому, чтобы ступать на рискованную тропу действий, хоть и не действующего сам по себе открыто."}),(0,i.jsx)(n.p,{children:"Её характер силён и неуступчив в принципиальных вопросах, она не готова пасть или склониться до конца превозмогающей во всех областях неведомой силе. И, вероятно, кто-то назовёт это величайшей глупостью, но для Джулии, с уже в одно время сломанной гордыней в неволе, не предстало подчиняться во второй раз, о чём она поклялась в ходе собственной казни. Ныне не готовая пресмыкаться и видеть кого-либо властным над собой, предпочитает реализовать себя как организатора одного из тех, кто “властен”: Джулия искренне убеждена, что способна повести за собой людей, не позволяя усомниться в себе — красивой, обольстительной и мудрой, являя собой того лидера, которого грешникам хотелось бы видеть."}),(0,i.jsx)(n.p,{children:"Вероятно, кто-то назовёт Джулию довольно жестокой и повелительной, в каком-то отношении строгой и наглой, однако выстроенный вокруг неё образ был и будет лишь образом: Контарини стремится быть справедливым и честным лидером, свободно позволяющим жить своим людям без излишних угнетений и злобы друг к другу, расовой ненависти и хаоса. Покой в каком-то отношении даже будет правильно назвать усладой для Джулии, позволяющей насладиться уже немолодой вуивре собственной империей."}),(0,i.jsx)(n.p,{children:"В её лидерстве нет чрезмерной бессердечности и неистовства, или же желания открыто добиться почитания, и подлиз, невзирая на большую любовь к себе, не воспринимает: для Джулии гиперболизация фактов — сущая глупость, она знает себе цену и без хвалебных комментариев. Те, кто соблюдает порядок и уважает вуивру, может рассчитывать на её особую поддержку. Невзирая на то, что Джулия кажется внешне суровой и довольно властной женщиной, как правило, все слуги, находящиеся под её опекой, чувствуют заботу и доброту, вероятную поддержку со стороны вуивры при наличии трудностей."}),(0,i.jsx)(n.p,{children:"Однако тот же эгоизм и самоуверенность позволяют женщине становиться нередким инициатором или же гостем опасных историй, говорящей об особой любви Джулии к загадочным и любопытным вещам: например, не ошибкой будет обмолвиться о том, каким жадным коллекционером побрякушек являет собой госпожа Джулия — вероятно, обустроенный ею дом вполне можно было бы обозвать личным оазисом, если не империей, и ради подобного Джулия готова рискнуть казалось бы всем."}),(0,i.jsx)(n.p,{children:"И хотя понапрасну девушка старается никого не дискредитировать, но даже так, Джулия считает, что существуют люди бесполезные, приносящие лишь вред или же бред, не должны существовать в “правильной” империи. Каждый, по её мнению, просто обязан приносить пользу, что говорит о Джулии как о практичной личности, требующей слаженности и отдачи в работе, за которую кто-либо возьмется, чего гарантирует и своим товарищам — ленивые люди ей особенно противны. Неумелых она может даже подбодрить, чувствуя в себе толику выраженного наставника, но тех, кто однажды сдался или проявил нежелание совершенствоваться, считает последним мусором. «Если ты не способен получить даже информацию — какая же от тебя польза?». И, кстати сказать, Джулия не любит то, что хотя бы единожды заклеймила “бесполезным”: каждое её ознакомление, наблюдение или же изучение информации, или же какое-либо действие, что необходимо по неким причинам, — всё обязано трактоваться тем, что способно сломать стены той лени и отчуждённости, восставшей вокруг легендарного замка особенно в нынешнем поколении."}),(0,i.jsx)(n.p,{children:"В противном случае заинтересовать Джулию и предрасположить её не представляется возможным — и конкретно здесь в ней расцветают лепестки безразличия, под действием аромата которых она будет непривычно апатичной и молчаливой снаружи. В её глазах редко встречается презрение, но одобрения встретить становится практически невозможно."}),(0,i.jsx)(n.p,{children:"При встрече такой души или же “бесполезной” вещи Джулия не гнушается выражать своё хладнокровие, совершенно не беспокоясь о прямолинейности собственных слов, отчего и не боится показывать личину ехидности и лукавости, насмехаясь над теми, кто трусливо поджал хвост и паразитирует на других. В какой-то степени этот образ и стал причиной слухов о её чёрствости."}),(0,i.jsx)(n.p,{children:"Вероятно, по этой причине она также ненавидит грешников малодушных, способных унижаться или позволяющих унижать себя: Джулия никогда не заставляет склоняться и показывать свою слабость перед ней, уважая умения и силы воли каждого с самого начала, как и право выбора. Со временем Джулия стала считать, что ей нужны искреннее уважение и поклонение. Без напыщенной любвеобильности. Также Джулией нельзя не заметить, что порой к представительницам своего же пола она куда более критичнее, на чём, вероятно, сказывалась окружающая её ещё при жизни обстановка."}),(0,i.jsx)(n.p,{children:"Нелюбовь к слабым людям вылилась буквально в то, что Джулия ценит сильных, гордых и достойно несущих себя личностей, исходя из чего склоняется с ними к товариществу или же дружескому соперничеству. Тех же, кто недостоин, неосознанно будет подталкивать к воспитанию такого же сильного характера, аккуратно, подобно наставнику, позволяя им проявить собственные качества под началом вуивры. Можно сказать, Джулия самостоятельно протянет руку таким личностям, желающим возрасти над собой."}),(0,i.jsx)(n.p,{children:"Сама по себе Джулия довольно миролюбива и не готова развязывать конфликт с кем ни попадя – противник должен того стоить. Угрозы со стороны противников, которых женщина отказывается уважать, как таковой не видит, исходя из чего предпочитает игнорировать. Джулия будет наказывать только тех, кто занимается вредительством и нарушает порядок, не гнушаясь использовать довольно грязные даже для неё методы, где она задействует, без сомнений, все свои козыри, которые припрятала глубоко в рукаве. Однако именно войну она ведёт лишь с достойными, где война вуивры будет величественной и гордой, не позволяющей опорочить ни своё имя, ни имя противника."})]})}),(0,i.jsx)(r,{title:"Страхи",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Насилие над женщинами",children:(0,i.jsx)(n.p,{children:"Джулия питает потаённый ужас к насилию или же жестокому обращению к женщинам в силу сохранившихся воспоминаний. Во время похищения очень многие венецианки оказывались под гнётом насмешек и жестокого обращения, даже если это и были «военные трофеи». Джулия чудом отделалась, однако психологическое здоровье вуивры на этот счёт оставляет желать лучшего. По этой причине очень категорично относится к проявлению кровожадности и жестокосердия, не обязательно даже к женщинам. Предпочитает избежать ненужных столкновений, если это возможно. Воспоминания о смерти тоже резонируют с этим страхом."})}),(0,i.jsx)(h,{title:"Дети",children:(0,i.jsx)(n.p,{children:"Девушка боится детей и их эмоций. Не потому, что они непредсказуемы, а потому что Джулии приходилось самостоятельно убивать, пусть и совсем маленьких. По этой причине получила глубокую психическую травму, боясь подходить к ним из чувства вины. Любое взаимодействие с детскими образами вызывает жуткий дискомфорт."})}),(0,i.jsx)(h,{title:"Турки и арабы",children:(0,i.jsx)(n.p,{children:"Очень напряжённо относится к грешникам юго-восточных стран, просто ненавидит по внешним критериям турков и арабов всей душой, хоть и способна держаться со всей выдержкой. Боится оставаться с ними наедине, поэтому крайне редко оказывается без сопровождения."})}),(0,i.jsx)(h,{title:"Разрушение дома",children:(0,i.jsx)(n.p,{children:"Разрушение собственного дома. Любое покушение на маленький оазис, возведённый усилиями многих, в том числе и Джулии, является её крепостью и душой. При попытке захвата своего дома или его разрушении просто сломается изнутри, невзирая на достаточно сильную волю. Это одна из немногих слабостей, способных повлиять на Джулию особенно сильно."})})]})}),(0,i.jsx)(r,{title:"Мечты, цели",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"Реализовать до конца маленькую империю. По очевидным причинам хочет в гармонии жить со своими подчинёнными, мочь защитить их от любых невзгод и обеспечить всем необходимым. Что-то сродни материнскому инстинкту или просто из чувственного понимания, как в действительности обращаются с рабами."}),(0,i.jsx)(n.p,{children:"Образумить мужа (Давена Брендена). Джулия отчаялась в попытках отговорить грешника от совершения мести, предлагая отказаться от мести, однако эта мечта не покидает её голову уже долгие годы. Всё же, слишком горячий нрав ей не под силу потушить, как бы не хотелось этого сделать. Однако, это не значит, что Джулия не желает поддержать того всеми силами или бросит."}),(0,i.jsx)(n.p,{children:"Быть счастливой с партнёром. Как-то раз Джулия думала о своей жизни и поняла, что в гареме ей жизни не было, а после него ей встретился отвратительный человек, убивший её прямо в доме."}),(0,i.jsx)(n.p,{children:"Джулия очень хочет однажды попасть на свою родину, назад, в Венецию. Душа давно тянет вуивру назад, однако из-за невозможности сбежать из рабства, была вынуждена смириться со своей судьбой."})]})}),(0,i.jsx)(r,{title:"Биография (при жизни)",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"История этой души прокладывает путь от начала 1563 года в Венеции, на северо-востоке нынешней Италии, связанной со знатным венецианско-патрицианским родом Контарини. Контарини были одной из старейших семей-основателей Венецианской Республики на тот момент, беря своё начало ещё с XI веков. И данный род, благодаря расширению собственного влияния, позволил на свет родиться плачевной истории навсегда потерянной девочки, имя которой – Джулия Контарини."}),(0,i.jsx)(n.p,{children:"Этому ребёнку повезло родиться на тот период в одном из самых богатых и аристократических домов тогдашней Венеции, на тот момент ведущих республику через одно из ключевых её достоинств – торговлю. Семья Джулии на тот период жила в одном из дворцов Венеции, расположенных на Гранд-канале района Каннареджо – Ка-д’Оро. Другое ныне памятное название – «золотой дом», выполненный в стиле венецианской готики. Она жила в этой семье со значимым человеком имения – Андриано Контарини, собственным отцом, имея множество братьев и сестёр, как и кузенов, с которыми девочка часто любила проводить время: почти все дворцы Контарини были расположены вокруг Гранд-канала, что позволяло расти во всеобщем внимании и не скучать."}),(0,i.jsx)(n.p,{children:"Но, конечно же, неполной любви: самой важной для себя частью взросления Джулия была главным образом обделена с детства – матерью. Когда девочка только родилась, к глубокому сожалению, роды оказались с немалыми осложнениями, и в скором времени уважаемая мадам Контарини, имя которой Джулия уже успела позабыть, скончалась. Впрочем, этого упущения отец допустить в семье не мог, а потому юная Контарини была окружена заботой и любовью не менее ласковой няни – Анны. И хотя многие углы на тот период позволили сгладиться благодаря своевременным мерам, проходя по Золотому дому, видя материнские портреты, в душе ребёнка поселилось любопытство и затаившаяся боль."}),(0,i.jsx)(n.p,{children:"Детство и подростковые годы Джулии проходили весьма спокойно, позволив девочке получить достойное образование в лице изучения литературы того времени, писания и прочего. У ребёнка был свой мир, внутри которого Джулия, словно молодой бутон, созревала. Состояние Контарини с трудом можно было назвать разрушенным несмотря на закрывшийся путь специй, ведь теперь увеличивалась торговля шёлком, хлопком и коврами из Леванта. Это ли не называется «родиться с серебряной ложкой во рту»? В одном из этих же подростковых лет старший Контарини дарит ей маленькое украшение в знак их большого обещания, что ещё успеет пронзить века и стать целью жизни."}),(0,i.jsx)(n.p,{children:"Впрочем, некоторые страницы со своей истории Джулия стереть не сможет никогда, как бы ей не хотелось забыть тёмные этапы собственной жизни: в 8 лет девочку, согласно всем обычаям и обязательствам, отправляют воспитанницей в аббатство, где Джулии придётся вдали от дома погрузиться в изучение католической веры и уединиться в службе богу с другими аристократками. Здесь Контарини оставит четыре года своей жизни, посвятив себя изучению языков, развитию умений чтения и писания, и, конечно же, мольбам Господу. В свободное время приходилось браться за пряжку и вышивку, попробовать проявить в себе талант искусства и как-то отличиться. Во многом, столь серый период жизни Джулия рада бы забыть навсегда, однако с теплотой она вспоминает писания писем своему отцу, но с ужасом – шалости духовных сестёр и суровость старших монахинь. С другой стороны, Джулия никогда не жалела о том, что воспитывалась в аббатстве: многие умения не только повлияли на её культурное просвещение и духовность, но и позволили особенно проявиться и в будущем спастись от начинаний с нуля."}),(0,i.jsx)(n.p,{children:"В возрасте 13 лет Джулия покидает монастырь и возвращается в отчий дом, всё также благоухающий в рассвете венецианских закатов. Однако, недолго продлилось счастье, так как в 1575 году вспыхивает чума Святого Карла, не на шутку приостановившая работу торговых суден. И хотя Венеция уже имела опыт борьбы с чумой, используя карантинные зоны для приходящих суден, однако трагичности эпидемии, отпечатавшейся на памяти Джулии, это не отменяет."}),(0,i.jsx)(n.p,{children:"В 1576 году, момент активного буйства мора, Контарини примут решение отправиться прямиком в сердце Священной Римской Империи, в Вену. Именно тогда происходит решающий эпизод: Джулия не смогла попасть в тот австрийский город, так как по дороге на них нападают люди из османской империи, разгромив весь экипаж."}),(0,i.jsx)(n.p,{children:"Как итог, отец не выживает, а о судьбе некоторых братьев Джулии до глубокой старости будет неизвестно. Её кузину — Кьяру, как и её саму, везут на турецкие земли, отправляясь буквально в сердце империи – Стамбул. Их перепродают с одного места на другое, буквально набивая цену, но пока что судьба обеспокоенных сестёр не успевала обрываться друг от друга. Лишь спустя длительное время Кьяра и Джулия попадают на Куриный рынок недалеко от главного стамбульского рынка, где через некоторое время их же и разъединят по разным путям. Кьяру забрали первой, решив преподнести одному из шейхов в дар, в то время как её саму купят только спустя несколько дней сновавшиеся люди из султанского гарема."}),(0,i.jsx)(n.p,{children:"Данную часть биографии Джулия вспоминает с болью на сердце: очень долгие путешествия изнуряли молодых девушек, более того, в компаниях они оказывались даже не одни, так как группа турецких пиратов не скупилась по пути грабить близ находящиеся деревни. Относились к ним хоть как и к товарам, однако общее обращение во многом оставляло желать лучшего. На этой почве Джулия получает глубоко отпечатавшуюся ненависть и страх к туркам, да и концепции насилия как таковой."}),(0,i.jsx)(n.p,{children:"С попаданием в гарем, Джулия сталкивается с такими же молодыми девочками, как и она сама – им всем было не больше 12-13 лет. Здесь путь Контарини начинался с простой рабыни – джарийе. Немаловажная ступень для ребёнка, оказавшегося в зверином логове, так как в этот период ей приходится отбросить аристократические привычки: в гареме приходилось работать и бегать так, как не заставляли даже в аббатстве. В конце концов, монастырь помнил, что род Контарини был одним из главных в Венеции и из богатых покровителей. В Османской империи же её кровь не значила ничего: калфы не питали особого дружелюбия и были строги, а юные девушки, мечтающие непонятно о чём, пытались добиться уважения и строить авторитет. Задетая гордость заставляет Джулию выкладываться на полную, она не готова была здесь погибать ни в каком виде, как и терпеть шалостей, способных обрасти клыками и откусить голову. Цель Контарини – вернуться любой ценой в Венецию, к своим родственникам, и узнать, что случилось с отцом (его смерть она не застала), попытаться найти сестру и братьев."}),(0,i.jsx)(n.p,{children:"Здесь начинается её путь усердия, в какой-то степени золотой период, где пришлось обучиться многому, причём, совсем иному, чему обучали её в родном доме: Джулии приходилось учить правила чтения Корана, османскую грамоту, основы ислама, так как без её принятия невозможно двинуться, обучиться тюркской культуре и заниматься рукоделием, танцами, музицированием. Также не забывалось обязательное обучение этикету для умения поддерживать светские беседы. И хотя раздражение росло с каждым днём, Джулия быстро провела параллели и поняла, что здесь у неё немного больше свободы, нежели было в монастыре. Возможно, именно благодаря этому ей становится на душе ненамного легче."}),(0,i.jsx)(n.p,{children:"Здесь же Джулия принимает новую веру и ей даруют новое имя – Эмине. Сначала над Джулией подшучивали и издевались, но, со временем, пару дерзких джарийе наказывались за смелость: Джулия отлично знала о порядках и дисциплине, а потому старалась аккуратно доносить катибе-уста (старшей калфе) об их шалостях, за что те получали дополнительные неприятности себе на голову, а Контарини – доверие и репутацию среди старших наблюдательниц за поддержание дисциплины."}),(0,i.jsx)(n.p,{children:"Три года Джулия, пока изучает новые правила и этикет, пытается привыкнуть к новому для себя миру. Новые традиции до конца жизни останутся для неё совершенно чуждыми, да и в глубине души ислам никогда не был ею любим."}),(0,i.jsx)(n.p,{children:"По достижении 16 лет, от внимания не ушло и сексуальное воспитание, подразумевающее получение навыков доставления удовольствия партнёру. На тот век Джулию можно было бы призначить к «отличницам», так как во всех отношениях девушка старалась преуспеть и показать себя, несмотря на высокую конкуренцию."}),(0,i.jsx)(n.p,{children:"Впрочем, шанса у Джулии выйти в фаворитки не появится: не только сама итальянка не желала подобной для себя участи, но и Мурад III до тех пор довольствовался связью лишь с одной женщиной – Сафие. Нежелание обрекать себя на участь наложницы, Контарини предпочитает взять всё в свои руки и попытаться построить своё будущее в гареме самостоятельно."}),(0,i.jsx)(n.p,{children:"Своими стремлениями достойно выделиться Джулия будет замечена Джанфедой-калфой, взяв юную джарие под материнское попечительство за верность, знания традиций, культуры и обычаев. Эта калфа была особенно известной в гареме своей верностью османскому роду, а потому набирала таких же, не менее достойных девочек. Тогда именно эта женщина под руководством Нурбану-султан занималась обучением наложниц в гареме, таким образом, позволив Джулии в будущем выйти на новую ступень в жизни. За своё прилежное и показательное поведение ей присвоят титул «усты», как знак того, что девушка отлично сдала контрольные зачёты. Как раз в 1580-м году Джулия удостоится прямого знакомства с валиде, что самолично принимали экзамен у молодых девушек, где Контарини достойно покажет себя перед госпожой Нурбану. Это позволило получить ей некоторую благосклонность и немного выделиться по статусу, и это же позволит Джулии, что иронично, спустя всего два года уже заниматься обучением других джарийе."}),(0,i.jsx)(n.p,{children:"Стало быть, будь это другие годы, у Джулии был бы шанс вырваться в статус икбал (постоянной фаворитки) — Джулия расцвела настоящей венецианской красотой. Однако ведущей фавориткой была и оставалась лишь одна женщина. И, мягко скажем, Джулия не горела желанием ложиться в постель к незнакомцу. Потому титул Контарини медленно перетекает в статус «одалык», говорящей об отсутствии интимной связи с султаном. Впрочем, в авторитете не теряет."}),(0,i.jsx)(n.p,{children:"Джулия продолжает проживать в гареме на полном обеспечении, начинает получать повышенное жалование. Она принимает решение нацелиться на карьерную службу, получив в своё время внимание со стороны валиде. Здесь итальянка начинает службу валиде Нурбану-султан вместе с Джанферой-калфой. Основная часть работы Джулии – это обслуживание своей госпожи, например, ей приходилось подавать шкатулку драгоценностей. И такой мелочной работы было много, так как обучение джарийе тоже входило в её обязанности. Большую часть времени Джулия старается аккуратно выделиться и найти своих сторонников, но верно продолжает следовать за султаншей и калфой."}),(0,i.jsx)(n.p,{children:"В 1583-м году, когда Джулии будет 20 лет, Нурбану-султан удостоилась пышным похоронам. Сама же Контарини предпочитает оставаться на стороне Джанфеды-калфы: в это время она становится одной из трёх могущественных и влиятельных женщин, даже не входя в султанский гарем. Калфа усиливает своё влияние на делах во дворце, её титул сохраняется самим султаном по просьбе почившей валиде, что позволяет Джулии вести спокойную и размеренную жизнь под крылом покровительницы. Калфа была умной интриганкой, что заставляло Джулию следовать разным приказам: это позволит Контарини перенять чужие секреты и недюжинный опыт, и оба этих факта девушка с готовностью унесёт в могилу. Эту преданность к делу Джанфеда особенно оценит."}),(0,i.jsx)(n.p,{children:"Калфа и одалык за компанию пользуются близостью с женщинами династии, за что начинают получать взятки и дорогие подарки. С репутацией и умениями калфы росли и связи Джулии, познакомившейся с главой белых евнухов и великими визирями. Таким образом, обе девушки накапливают солидное богатство."}),(0,i.jsx)(n.p,{children:"И даже попытка поднять восстание с требованиями казнить министра и калфу ситуацию удалось решить благодаря вмешательству султана, что сохранило и положение Джулии, остававшейся тенью Джанфеды."}),(0,i.jsx)(n.p,{children:"Через несколько лет калфа начинает заниматься благотворительностью и отходит от активной политики, выйдя на пенсию, в то время как Джулия наведывается к своей старой подруге – Сафие – и предпочитает посвятить своё время для службы ей. Причиной подобного решения становится тот факт, что ещё не прошло достаточно времени для покидания гарема, а сбежать возможности с деньгами не представлялось."}),(0,i.jsx)(n.p,{children:"Жизнь Джулии во время службы Сафие меняется кардинально: растущее могущество фаворитки и происходящие вокруг всего интриги погружают одалык с головой. Когда Джулия оставалась на стороне Нурбану, ей доверяли не так много дел, но здесь, наученная опытом и желающая показать себя Джулия имела всю сцену перед собой. Здесь же впервые Контарини придётся доказать свою верность и отравить одну дерзкую икбал, что забеременеет от султана и начнёт создавать угрозу госпоже своим нарастающим авторитетом. Яд заставит зазнавшуюся рабыню спуститься с небес на землю и потерять ребёнка на приличном месяце беременности. Хорошо подготовленная сцена позволит Контарини выбиться в статус верной «пейк», став преданной помощницей тогдашней хасеки Сафие-султан."}),(0,i.jsx)(n.p,{children:"В этом статусе девушка проживёт ещё немало лет, верной тенью следуя за Сафие-султан. Для поддержания своего статуса и веры ей придётся совершить немало прегрешений на душу, но свобода была близка. В 1589 году Джулия, в свои 29 лет, просит госпожу покинуть гарем, несмотря на то, какие почести получала. Сафие-султан даёт своё разрешение: в течение многих лет Джулия совсем не имела никаких отношений, что могло позволить освободить её от рабства, наделив домом и регулярными выплатами до конца жизни. Однако для этого следовало выйти замуж, что Джулию не радовало, но это был единственный билет на свободу. Впрочем, этот билет будет стоить итальянке жизни: из-за невероятной образованности и традиционного воспитания девушек мечтали взять в супруги многие государственные служащие империи. Сложно было сказать, что большая их часть была с чистыми намерениями."}),(0,i.jsx)(n.p,{children:"Со своими богатствами и приданным Джулия отправляется в новый дом. Втихую она старается найти хоть какую-то информацию о своей семье и родных, а ещё лучше – как-нибудь сбежать. Однако муж следил за ней, и пригрозил, что она навсегда останется с ним и никуда не поедет. Он всячески ограничивал девушку, а потом взял силой. Пробудившаяся ненависть, спящая все эти годы, и невозможность вернуться домой, не дают Контарини сдаться."}),(0,i.jsx)(n.p,{children:"Но губительно на психику итальянки с течением времени влияет не только отсутствие способа выбраться, но и факт того, что приходится ложиться в осточертевшее ложе. Испытав неоднократное унижение, заметно худшее, нежели было пережито ею в гареме, через некоторое время она узнаёт о своей беременности. Возможно, с этой новостью мятежный дух и успокоился бы, но Джулия предпочитает закончить всё иначе, питая глубокую ненависть как к мужу, так и к своему будущему ребёнку."}),(0,i.jsx)(n.p,{children:"Итальянка получает в свои руки яд и выпивает его, спровоцировав у себя чудовищную лихорадку и соответствующий выкидыш. В порыве бреда Контарини попытается даже убить мужа, однако им же будет и задушена в декабре 1595-го года за свою попытку покушения на сановника."})]})}),(0,i.jsx)(r,{title:"Жизнь в Энкраже",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"Свою смерть Контарини встретила… никак. Сложно было описать эмоции девушки, испытавшей тяжёлое эмоциональное потрясение, близкое к депрессии, за последние четыре года жизни. Первые мгновения для неё выглядели опустошенно: она не помнила, что произошло, но это продолжало душить изнутри. Но, в конце концов, о содеянном долго Джулия сожалеть не желала, так как к ней пришло осознание смерти, а значит – свободы. Что она, наконец, сможет начать всё с самого начала, к чему и рвалась всю жизнь, когда она по какой-то случайности повернула не туда."}),(0,i.jsx)(n.p,{children:"Именно в башне Контарини смогла взглянуть на себя с другой стороны, пока проходила испытания, и вспомнила о своём обещании, заметив на шее прикрытый кулон с фамильным кольцом рода."}),(0,i.jsx)(n.p,{children:"Именно благодаря отцовскому кольцу девушка заостряет окончательную мысль, что она – Джулия Контарини, венецианская аристократка. Её рабское прошлое стёрто с лица земли и хранится лишь в её сердце и забытом имени «Эмине». Это позволяет по прибытии в замок расцвести мотивации Джулии и взять всё в свои руки."}),(0,i.jsx)(n.p,{children:"Величественной, но ещё совсем юной вуивре не хотелось никому показываться — она слаба перед здешними силами. А, значит, может попасть к нежеланным людям – и тогда история повторится. Первые годы она, как маленький зверёк, скрывается в библиотеке, став там постоянным обитателем, и поглощает новые знания, большинство из которых при жизни казались такими недоступными. В глубокой тишине Джулия изучала из новых писаний культуру людей, читала о науке, истории и, конечно же, сути данного места. Особенно её заинтересовала история собственной расы и то, кем она являлась. Однако собственное развитие нельзя было останавливать исключительно на книгах."}),(0,i.jsx)(n.p,{children:"По этой причине Джулии приходится находить укромное место и тренировать магические способности. Книги подсказали ей, что свет в этом мире был губительным и его здесь почти не было, вуивры часто владели именно огнём. Джулия, впервые попробовав воспользоваться силами, создала маленький осколок света. Суть его была весьма безобидна, однако одновременное изумление и трепет охватили вуивру в тот момент. Это дало толчок к последующему развитию способностей. Для этого Контарини специально искала укромные места, в которых её никто не сможет найти. Вуивра начинает понимать, что ей не хватает и хороших навыков для самозащиты. Это стало толчком к тому, чтобы взять в руки меч и попытаться с ним совладать. Одновременно с этим она старается найти упоминания о своей семье в тёмном мире, но поиск был безуспешен."}),(0,i.jsx)(n.p,{children:"Через некоторое время девушка отправляется в Сады Семирамиды, на территорию Зверя Греха, где в будущем и будет долгое время находиться. Контарини пыталась избежать не только внимания более сильных вуивров, но и обезопасить себя от возможных угроз. Просторные земли сада и милость Императорского змея позволили Джулии погрузиться в себя и наблюдать со стороны за остальными представителями алчности. В частности, ей были интересны и другие змеи, но Джулия заставляла себя оставаться в тени, пока не почувствует, что готова."}),(0,i.jsx)(n.p,{children:"Впрочем, чему именно Джулия не изменяла – это чтению традиций и почитаний Императорского Змея. Невзирая на своё отшельничество, Контарини с большим удовольствием участвовала на ритуалах, а на одном из них имела честь наблюдать одного из змей, кого нарекли в будущем Хранителем Огня — Давеном Бренденом. Здесь же она видела и прошлую Королеву змей, как и её верных последователей, в число которых войдёт и одна темнокожая женщина — Миллисент Уайт."}),(0,i.jsx)(n.p,{children:"Однако, Джулии оставалось только наблюдать за величием других. У неё очевидно была цель, но не хватало уверенности, не хватало опытности. Лишь изредка вуивра наведывалась к мудрому Императорскому Змею, постигая чужие наставления."}),(0,i.jsx)(n.p,{children:"Настолько впечатлилась девушка его мудростью и старостью, внемля речам, что в свободные минуты после занятий, наведывалась к Змею и разделяла с ним тоскливую вечность тянущегося времени. Смышленость и основательные познания в окружающем, хорошая наблюдательность и тихая жизнь в садах, не вдогонку за властью, а главное — политическая нейтральность позволили Джулии обрести свою роль в глазах Императорского Змея."}),(0,i.jsx)(n.p,{children:"К своим 100 годам, одним из подарков, оставленных для Джулии за проведённое время с Императорским змеем, он одарил девушку почётным титулом Стража греха."}),(0,i.jsx)(n.p,{children:"Змей нарёк её весьма говорящим и необычным прозвищем «Жрица Солнца», позволив Контарини дебютировать перед вуиврами на следующем Вознесении, явившись в числе проводников величественного шествия и служителей. Это позволило Джулии стать «глазами» Зверя Греха и нести часть его воли, оставляя за собой независимость от влияния других вуивров."}),(0,i.jsx)(n.p,{children:"Когда Контарини была готова проявить свою силу, Императорский Змей отправил ее на северные земли и просит присоединиться к одному из логов, где девушке следует нарастить свой авторитет. Поступив, согласно совету Зверя, вуивра выбирает одно из таких, самое обычное и простенькое логово, где сможет оказать небольшую поддержку её держателю, что в будущем станет хорошим другом. Сама же вуивра за своё покровительство получала драгоценности и мирно обзаводилась богатством и уважением младшего змеиного общества. Таким образом появилось спокойное логово, в котором Контарини чувствовала себя превосходно. Вместе с этим, сила Джулии служила «светом во тьме», так как опасность северных земель обсуждалась во всех уголках висячих садов."}),(0,i.jsx)(n.p,{children:"Ближе ко второму веку, Джулия столкнётся с амбициозным мужчиной, что успел впечатлить змеиное общество и удостоится особого внимания со стороны Зверя Греха – Давеном. Императорский Змей настоял наблюдать за каждым восходящим змеем. Она была наслышана о том, что Хранитель Огня собирал вуивров для воссоздания могущественного двора, однако сама же Джулия относилась к нему весьма недоверчиво и осторожно. Ей пришлось выдвинуть ненужные для себя, но требования, которые могли бы проверить искренность дела Давена и способность отвечать за свои слова. Только после этого Жрица присоединяется и начинает внимательно наблюдать за деяниями вуивра, поддерживая в нелёгком деле."}),(0,i.jsx)(n.p,{children:"С прохождением века, границы между двумя змеями, как таковые, стираются: Джулия проникается преданностью и более охотно смотрит на чужую мечту, соглашаясь следовать ей. Это позволяет вуивре прислушаться к себе и своим желаниям, обзавестись в её понимании некоторой любовью. И через какое-то время они играют свадьбу, однако торжественное заявление Давена предостерегает Джулию быть внимательнее к происходящему, так как в скором времени должно было воспылать новое соперничество змей, когда Королева Виллинда покидает свой пост, оставив после себя наперсницу Миллисент, с которой Джулии тоже удостоилось познакомиться."}),(0,i.jsx)(n.p,{children:"Когда появились известия о новой самопровозглашённой королеве, Джулия серьёзно готовится к тому, что последует дальше. Как только Давен пропадает после путешествия, вуивре приходится столкнутся с весьма тяжёлой ситуацией: Миллисент Уайт набирала силы и не собиралась бездействовать, когда известия об исчезновении Давена подтвердились. Контарини начинает вести переговоры, стараясь не допустить сражения, как раз в ходе которых получше узнаёт гордую темнокожую соперницу, открывая в себе симпатию к величию и её образу. Джулия позже признается, что женщина напомнила ей если не султанш, то дорогую калфу, с которой Джулия прошла огонь и воду."}),(0,i.jsx)(n.p,{children:"Сдерживать нарастающий накал вечно было нельзя, а потому следовало Давену вернуться и узнать обо всей ситуации, как тут же разгорается битва, ставшая роковой: Хранитель Огня проигрывает и оказывается в подвешенном состоянии, что вынуждает Джулию вступить в открытый диалог с Миллисент и поторговаться за чужую свободу и жизнь благодаря своему положению, взяв на себя ответственность за Давена. Вероятно, именно хорошо отпечатавшееся впечатление и уважение женщин друг к другу позволяют ситуации пройти спокойнее, хотя Джулия искренне хотела больше дружить, чем становиться против Уайт. Но, будучи верной Давену, отступает с ним и небольшой численностью слуг на север."}),(0,i.jsx)(n.p,{children:"В момент выхаживания Брендена, Джулия открывает в себе дар исцеления, позволяя облегчить боль мужа. В этот же период девушка просит совета Императорского Змея, ей не хватало сил со всем справиться: севернее земли стали яростнее, выживать в них было сложнее. Её ответом была простая фраза: «Рубин – твоя искра»."}),(0,i.jsx)(n.p,{children:"Контарини остаётся рядом с Давеном вплоть до полного выздоровления. Понимая, что того гложет поражение и разорение своего логова, в 20 веке Джулия принимает решение провести повторные переговоры для обсуждения условий возвращения с Миллисент. Это позволяет логову получить билет обратно на западные территории, но требует уйти под властвующую руку Миллисент. Джулия без сомнений соглашается с вассальством и переходит под начало змеиной королевы, но просит в знак уважения возможность самостоятельно наблюдать за Давеном и держать его под контролем."}),(0,i.jsx)(n.p,{children:"Контарини постаралась обеспечить мужу всё, что в её силах, оставшись подле руки Миллисент, лишь изредка покидая её по личной прихоти. Теперь стражу греха предстояло изучить ещё одно крупное логово, его правила, общество, ну и, конечно же, его ведущий зенит – змеиную королеву. И получить прощение Давена за подобное своевольное «предательство»."})]})})]}),(0,i.jsxs)(r,{title:"Дополнительно",children:[(0,i.jsx)(r,{title:"Факты о персонаже",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Свобода имени",children:(0,i.jsx)(n.p,{children:"Невзирая на свою большую преданность при жизни султанше и принятие мусульманской веры, именно в Энкраже девушка почувствовала свободу и решилась вновь пользоваться своим именем — таким образом она сказала себе, что теперь больше никто над ней не властен."})}),(0,i.jsx)(h,{title:"Имя Эмине",children:(0,i.jsx)(n.p,{children:"При принятии ислама девушке дали имя “Эмине”, означающее искренность, честность и заслугу доверия. И правда, глубокой преданностью вуивра не обделена."})}),(0,i.jsx)(h,{title:"Связь с Джанфедой",children:(0,i.jsx)(n.p,{children:"Джанфеда-калфа, как только вышла на пенсию, и Эмине-одалык поддерживали общение вплоть до отъезда второй, письмами. При жизни с мужем все её письма прочитывались, а потому она потеряла связь с той, кто её воспитал."})}),(0,i.jsx)(h,{title:"Побег",children:(0,i.jsx)(n.p,{children:"Джулия вышла на след своих других родственников и пыталась сбежать из дома, однако муж запер и наказал девушку. На тот момент он совсем отвратительно относился к Джулии, так как она не могла четвертый год понести ребёнка."})}),(0,i.jsx)(h,{title:"Стиль одежды",children:(0,i.jsx)(n.p,{children:"Джулия предпочитает следовать строгому стилю своего времени, а потому носит платья с выразительными узорами и прикрытыми руками вплоть до кистей. Различные вырезы, декольте и шнуровки ей непривычны, хотя пару раз бывали моменты, когда вуивра одевалась в подобные греческому стилю платья, обнажая плечи с руками. Джулия себе практически не позволяет подобной вольности, а потому даёт телу вдохнуть свободы только в исключительные случаи."})}),(0,i.jsx)(h,{title:"Бинт на руке",children:(0,i.jsx)(n.p,{children:"На левой руке Джулия стала носить бинт, который периодически меняет. Началось это совсем недавно, и причиной подобного является недавно оставленный ожог по неаккуратности."})}),(0,i.jsx)(h,{title:"Рубиновый глаз",children:(0,i.jsx)(n.p,{children:"Когда-то свой рубин девушка хранила на ожерелье, однако после поражения мужа и изгнания на опасные земли, чтобы быть способной защитить логово, Джулия вживила его буквально себе в глаз с надеждой на получение силы. По этой причине левый глаз изменился, став ярче любой алой звезды, и зрачок стал вечно горящим пламенем внутри неё. Говорят, если в него долго смотреть, то можно увидеть раскаливание огня, подобно тому, как наблюдаешь за сиянием солнца. Сама Джулия этим глазом видит отлично."})}),(0,i.jsx)(h,{title:"Свечение в темноте",children:(0,i.jsx)(n.p,{children:"Рубиновый глаз Джулии крайне чувствителен к темноте, а оттого любое его нахождение во тьме провоцирует девушку выделять ауру интуитивно. Так, например, она способна оставлять за собой сияющие следы."})})]})}),(0,i.jsx)(r,{title:"Внешность",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"Рабынь никто не рисовал, даже если они обладали хоть каким-нибудь титулом. Разве это было возможно? Один мастер ухитрился запечатлеть вышедшую из-под опеки гарема на тот момент Эмине. Она настоящая, словно орлица, венецианская дочь – Джулия Контарини – стала портретом совсем юного художника, полного пылкого огня в сердце, воспитанного пёстрым нравом и, совсем нежного, но уверенного шага на забытом произведении. Такой художник оставил лёгкими движениями мимолётные очертания, приоткрывая таинства тысячи ночей, сошедшихся на одном небе."}),(0,i.jsx)(n.p,{children:"В своём рисунке он выразительно изображает мягкими линиями аристократическую осанку, описывает величие и грацию в одном серебряном флаконе, заполненным кисло-сладким вином сдержанности и рассудительности. Углём он запечатлел контраст богатых тёмных и белых тонов, изобразил женское коварство в глубоком омуте, на дно которого так и манило опуститься, но грань всегда оставалась выдержанной."}),(0,i.jsx)(n.p,{children:"Её ухоженности могло позавидовать немало невольниц и простых рабынь, ведь сейчас перед нами – свободная женщина, пусть и не госпожа, собранная и отправленная к мужу на милость султанши. Волосы Джулии зачастую в положении приподнятого пучка и плотно закручиваются, закалываются перелитыми золотом изысканными украшениями кривообразной формы с изображением роз или же молодой веточки. И хотя этот образ во многом привычнее всего остального, нельзя забывать о вечной красоте свободы: блондинистые локоны, дай им только волю, становятся бегущей рекой и опадают совсем вниз, достигая прикрытых колен. Невзирая на свою бархатистость и, вероятно, ломкость, они воздушны и густы, завиваются при неловком роспуске после длительного ношения их прикрытыми. Турчанки умели ухаживать за своими волосами."}),(0,i.jsx)(n.p,{children:"Но восхищения достойны и выразительные черты лица: они были плавны и мягки, но не сильно, всё-таки чутка вытянуты, вырисовывая грациозный овал лица со слабо выраженными скулами, с приподнятым и заострённым носиком и пухлыми губами. В ней ещё не выдавались старческие черты, Джулия погибла молодой, а потому морщинок и вовсе не сохранилось на бескрайнем чистом лбу, которого касались звёздные дожди. Словно она была куклой, но такого мастера, чьи руки были могущественнее Бога."}),(0,i.jsx)(n.p,{children:"Особое внимание следует уделить украшениям, ведь, кажется, они имеют некоторый скрытый смысл. Художник с кропотливостью вырисовывал золоченные серьги слегка выгнутой формы с клипсовым замком. Вторым элементом бижутерии служило, одним из самых важных, маленькая цепочка византийского якорного плетения, отличающееся особой витиеватой формой со спаянными под прямым углом звеньями, с фамильным кольцом дома Контарини. В будущем здесь покажется с волнением хранимый рубин, так оберегаемый вуиврами. Впрочем, что сейчас, то и потом – перстень не терял своей ценности."}),(0,i.jsx)(n.p,{children:"На обратной стороне помятого портрета, наброшенного невероятной скоростью, ведь за ураганом угнаться способен только ветер, отмечался средний рост девушки (165 см), и ей была посвящена целая поэма, сочиненная, стало быть, именно талантливым мальчиком. Слова были абстрактны, но торжественно восхваляли красоту спустившегося с небес солнца. С листов вырывалось воспевание и её женских глаз, сравнимых с серной, и они сияли чудесами морского бриза, хотя, казалось, были отчего-то пустыми, пока румяна отдавали цветом сочного персика, а губы прикрывались рукой и что-то нашёптывали суетливым. Стало быть, если бы эта миловидная девушка, подобная одинокой берёзе, последовала за мальцом, то избежала бы глухой участи."}),(0,i.jsx)(n.p,{children:"Но этот рисунок был найден и сожжён бывшим мужем Джулии. Казалось бы, какая жалость? Впрочем, зачем же нам теперь портреты забытых веков, когда здесь и сейчас незримое отражение кристально чистой воды глядит по ту загробную сторону? И находит ту самую, Джулию Контарини. Но и глаза её теперь полны совсем других эмоций, а главное, сияют золотом и гремящим пламенем."})]})}),(0,i.jsx)(r,{title:"Навыки и умения",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Венецианская школа фехтования",children:(0,i.jsx)(n.p,{children:"Невзирая на то, что девушка не имела возможности при жизни получить подобного рода образование, в Энкраже ситуация кардинально поменялась со взглядами Джулии. На практике, вуивра проводит тренировки тайно и самостоятельно, обучившись сражаться одноручными мечами."})}),(0,i.jsx)(h,{title:"Домашнее хозяйство",children:(0,i.jsx)(n.p,{children:"Жизнь Джулии быстро заставила избавиться от прозвища «белоручки» при гареме, а потому с вышиванием и вышивкой, готовкой и уборкой способна справиться."})}),(0,i.jsx)(h,{title:"Танцы и музыка",children:(0,i.jsx)(n.p,{children:"Преимущественно, восточного характера, которым девушка была обучена в гареме. Невзирая на образование, на тот период европейским танцам в Венеции не обучали. Если говорить о музыке, то с этой стороны Джулия весьма способна: она часто играла на струнных удах и тростниковой флейте в небольших оркестрах из рабынь. Однако, сама же Джулия влюблена в персидские арфы."})}),(0,i.jsx)(h,{title:"Языки",children:(0,i.jsx)(n.p,{children:"У Джулии наблюдается хороший потенциал к изучению языков, что позволило ей выучить несколько из таких: латынь для Библии, итальянский, османский, персидский, арабский и немецкий."})}),(0,i.jsx)(h,{title:"Этикет и преподавание",children:(0,i.jsx)(n.p,{children:"У девушки превосходные манеры и знания этикета в прожитых странах, как и неплохие умения передавать какие-либо знания преподаванием."})}),(0,i.jsx)(h,{title:"Выносливость",children:(0,i.jsx)(n.p,{children:"Благодаря тяжёлому труду в гареме у девушки хорошая выносливость к нагрузкам и длительной работе. Данный спектр усиливается занятиями физической подготовкой с мечом."})}),(0,i.jsx)(h,{title:"Внимательность и приспособляемость",children:(0,i.jsx)(n.p,{children:"Хорошая внимательность и приспособляемость к внезапным ситуациям."})}),(0,i.jsx)(h,{title:"Финансовое дело",children:(0,i.jsx)(n.p,{children:"Научилась управляться с финансами, а в Энкраже – развила навыки финансового дела."})}),(0,i.jsx)(h,{title:"Переговоры",children:(0,i.jsx)(n.p,{children:"Толк ведения переговоров."})}),(0,i.jsx)(h,{title:"Наблюдательность",children:(0,i.jsx)(n.p,{children:"Умение подмечать малозначительные детали и запоминать их."})}),(0,i.jsx)(h,{title:"Знания об Императорском Змее",children:(0,i.jsx)(n.p,{children:"Большие знания об Императорском Змее."})})]})}),(0,i.jsx)(r,{title:"Слабости",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Слияние с безумной силой",children:(0,i.jsx)(n.p,{children:"Джулия пошла весьма на отчаянный шаг, когда решилась вживить рубин. Так, если Джулия попытается воспользоваться Мерцаниями высшей категории более положенного, она может сгореть заживо в безумном пламени без возможности воскреснуть. По этой причине глаз настоятельно блокирует способность."})}),(0,i.jsx)(h,{title:"Блокирование способностей",children:(0,i.jsx)(n.p,{children:'После полного использования высшей категории Мерцания, Джулия не способна пользоваться "Отрицательной" веткой, а большая часть способностей «Рубинового» сияния ослабляется. Таким образом, девушка остаётся беззащитной.'})}),(0,i.jsx)(h,{title:"Левый глаз",children:(0,i.jsx)(n.p,{children:"Здесь вуивру очень нелегко застать врасплох и ранить, но если это сделать и вывести из строя, то ранение нивелирует работоспособность «Рубинового сияния» и резко снижает ранг Мерцания, закрывая доступ использования высшей категории. Обильное кровотечение из глаза тоже нарушает работу способностей, с перебоями и глубокой болью. При тяжёлой перегрузке глаз может взорваться, лишая девушку магических способностей."})}),(0,i.jsx)(h,{title:"Ожоги и ушибы",children:(0,i.jsx)(n.p,{children:"На теле девушки часто бывает огромное количество ожогов или же ушибов. По этой причине, невзирая на хорошую физическую выносливость, при наличии таких ранений может быстро выбиться из сил или и вовсе побоится вступать в сражение, пытаясь оценить свои возможности здраво."})}),(0,i.jsx)(h,{title:"Отсутствие кровожадности",children:(0,i.jsx)(n.p,{children:"Джулия не обладает кровожадностью, чтобы убить противника или жестоко лишить его чего-либо, хоть и умеет плести интриги и солить. Этим всегда можно воспользоваться и нанести вуивре удар в неожиданный момент, так как девушка никогда не уничтожает противников полностью, но считает свою меру «достаточной», чтобы заставить противника потерять мотивацию."})}),(0,i.jsx)(h,{title:"Шантаж близкими",children:(0,i.jsx)(n.p,{children:"Скорее всего поведётся на шантаж, если взять близкого друга под контроль и реально пригрозить его убийством, без шуток. Точно поведётся, если это будет Давен, так как сильно дорожит им."})}),(0,i.jsx)(h,{title:"Отсутствие боевого опыта",children:(0,i.jsx)(n.p,{children:"Отсутствие боевого опыта сильно сказывается на Джулии. Хоть девушка и знает меру своим силам и осторожно их использует, перехитрить вуивру не составит труда, а в ближнем – проиграть заведомо опытному в битвах противнику."})}),(0,i.jsx)(h,{title:"Низкочастотные вибрации",children:(0,i.jsx)(n.p,{children:"Неприятны низкочастотные вибрации."})}),(0,i.jsx)(h,{title:"Уязвимость к холоду",children:(0,i.jsx)(n.p,{children:"Из-за фактического отсутствия магии огня, не испытывает слабости к водным расам при сражении с ними, однако уязвима к низким температурам особенно сильно из-за прямого контакта с рубином. А его опасно держать на холоде."})})]})}),(0,i.jsx)(r,{title:"Связанные персонажи",children:(0,i.jsx)(d,{children:(0,i.jsx)(h,{title:"Адриано Контарини",children:(0,i.jsx)(n.p,{children:"Людской мир. Отец вуивры, от которого девушка была оторвана в ходе жизни. Единственное напоминание о Контарини – памятное кольцо, которое Джулия сквозь огонь и воду пыталась сохранить как единственное напоминание о семье и крови."})})})})]}),(0,i.jsx)(x,{children:(0,i.jsx)(n.p,{children:"Ты хотел приласкать всех чудовищ. Теплое дыхание, немного мягкой шерсти на лапах – и ты уже готов был полюбить и привлечь к себе"})})]})}function s(e,i){throw Error("Expected "+(i?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}e.s(["default",0,function(e={}){let{wrapper:s}={...(0,l.useMDXComponents)(),...e.components};return s?(0,i.jsx)(s,{...e,children:(0,i.jsx)(n,{...e})}):n(e)}])}]);